from itertools import product

def tiles(grid):
 cells={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v}
 opts=[]
 # squares
 for r,c in cells:
  t={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if t<=cells: opts.append((t,1))
 # L trominos 2x2 missing one
 for r in range(len(grid)-1):
  for c in range(len(grid[0])-1):
   b={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
   for missing in b:
    t=b-{missing}
    if t<=cells: opts.append((t,missing))
 def rec(left,chosen):
  if not left:
   yield chosen;return
  x=min(left)
  for t,col in opts:
   if x in t and t<=left:
    yield from rec(left-t,chosen+[(t,col)])
 return list(rec(cells,[]))
